return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ne_NP','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'तपाईंको WordPress फाइलहरू र डाटाबेसलाई तपाईंको आफ्नै भण्डारणमा ब्याकअप गर्दछ — Dropbox, Google Drive, Cloudflare R2, Amazon S3 वा कुनै पनि S3-कम्प्याटिबल बकेटमा — तिनीहरूलाई एकै पटकमा पुनर्स्थापना गर्दछ, र अन्य ब्याकअप तथा माइग्रेसन प्लगइनहरूद्वारा सिर्जना गरिएका ब्याकअपहरू आयात गर्दछ।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'ब्याकअपहरू','Get Pro: schedules, several storages, encryption'=>'Pro प्राप्त गर्नुहोस्: तालिकाहरू, धेरै भण्डारणहरू, गुप्तिकरण','Working…'=>'काम भइरहेको छ…','Finished'=>'सम्पन्न भयो','Failed'=>'असफल भयो','Cancelled'=>'रद्द गरियो','Cancel'=>'रद्द गर्नुहोस्','Restore'=>'पुनर्स्थापना गर्नुहोस्','Delete'=>'मेटाउनुहोस्','Delete this backup from your storage? This cannot be undone.'=>'यो ब्याकअप तपाईंको भण्डारणबाट मेटाउने? यो कार्य पूर्ववत गर्न सकिँदैन।','No backups yet. Press “Back up now” to make the first one.'=>'अहिलेसम्म कुनै ब्याकअप छैन। पहिलो सिर्जना गर्न "अहिले ब्याकअप लिनुहोस्" थिच्नुहोस्।','Reading your storage…'=>'तपाईंको भण्डारण पढ्दै…','a complete backup, as opposed to an incremental oneFull backup'=>'पूर्ण ब्याकअप','a backup holding only what changed since an earlier oneIncremental backup'=>'इन्क्रिमेन्टल ब्याकअप','Encrypted'=>'इन्क्रिप्ट गरिएको','From another site'=>'अर्को साइटबाट','Database'=>'डेटाबेस','Files'=>'फाइलहरू','Uploading %1$s: %2$s%%'=>'%1$s अपलोड गरिँदैछ: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'खुलेको विन्डोमा Dropbox मा साइन इन गर्नुहोस्, त्यसपछि Dropbox ले तपाईंलाई देखाएको कोड टाँस्नुहोस्:','Saved.'=>'सुरक्षित गरियो।','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'यस गन्तव्यलाई प्लगइनबाट हटाउने? यसमा भण्डारण गरिएका ब्याकअपहरू मेटिने छैनन्।','Reload the page to see the restored site.'=>'पुनर्स्थापित गरिएको साइट हेर्न पृष्ठ पुन: लोड गर्नुहोस्।','Storage'=>'भण्डारण','Import & migrate'=>'आयात र स्थानान्तरण गर्नुहोस्','Settings'=>'सेटिङहरू','Sections'=>'खण्डहरू','Google Drive is connected.'=>'Google Drive जडान भएको छ।','Google Drive could not be connected.'=>'Google Drive जडान गर्न सकिएन।','Details'=>'विवरण','Back up now'=>'अहिले ब्याकअप गर्नुहोस्','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'ब्याकअपहरू तपाईंको आफ्नै भण्डारणमा जान्छन्, यो सर्भरमा होइन। पहिले <a href="%s">आफ्नो भण्डारण जडान गर्नुहोस्</a>।','What to back up'=>'के ब्याकअप गर्ने','Files and database'=>'फाइलहरू र डाटाबेस','Database only'=>'डाटाबेस मात्र','Files only'=>'फाइलहरू मात्र','Note (optional)'=>'टिप्पणी (वैकल्पिक)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'अर्को भाग बनाउनु भन्दा पहिले प्रत्येक भाग तपाईंको भण्डारणमा अपलोड गरिन्छ र यो सर्भरबाट हटाइन्छ, त्यसैले ब्याकअपले तपाईंको होस्टिङमा कहिल्यै ठाउँ लिँदैन।','Your backups'=>'तपाईंको ब्याकअपहरू','Refresh'=>'ताजा गर्नुहोस्','Restore this backup'=>'यो ब्याकअप पुनर्स्थापना गर्नुहोस्','Passphrase'=>'पासफ्रेज','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'म बुझ्छु कि यसले यो साइटको फाइलहरू र डाटाबेसलाई ब्याकअपको साथ प्रतिस्थापन गर्दछ। ब्याकअपमा नभएका फाइलहरू राखिन्छन्।','Recent activity'=>'हालको गतिविधि','Backup'=>'ब्याकअप','Restore / import'=>'पुनर्स्थापना गर्नुहोस् / आयात गर्नुहोस्','Running'=>'चलिरहेको छ','Your storage'=>'तपाईंको भण्डारण' . "\0" . 'तपाईंका भण्डारण गन्तव्यहरू','No storage yet. Choose where your backups go below.'=>'अहिलेसम्म कुनै भण्डारण छैन। तपाईंको ब्याकअपहरू कहाँ जाने भनेर तल छान्नुहोस्।','Ready'=>'तयार छ','Not connected'=>'जडान गरिएको छैन','Connect'=>'जडान गर्नुहोस्','Test'=>'परीक्षण','Edit'=>'सम्पादन गर्नुहोस्','Remove'=>'हटाउनुहोस्','Add storage'=>'भण्डारण थप्नुहोस्','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'ब्याकअपहरू एउटा भण्डारण गन्तव्यमा जान्छन्। फरक प्रयोग गर्न, माथिको सम्पादन गर्नुहोस् वा हटाउनुहोस्।','Kind of storage'=>'भण्डारणको प्रकार','Name (for you)'=>'नाम (तपाईंका लागि)','Provider'=>'प्रदायक','Cloudflare account id'=>'Cloudflare खाता आईडी','Endpoint address'=>'अन्त्यबिन्दु ठेगाना','Region'=>'क्षेत्र','Bucket'=>'बकेट','Access key id'=>'पहुँच कुञ्जी आईडी','Secret access key'=>'गोप्य पहुँच कुञ्जी','Leave empty to keep the saved key'=>'सुरक्षित गरिएको कुञ्जी राख्न खाली छोड्नुहोस्','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Cloudflare R2 का लागि: Cloudflare ड्यासबोर्डमा R2 खोल्नुहोस्, एउटा बकेट सिर्जना गर्नुहोस्, त्यसपछि “Manage R2 API tokens” → त्यो बकेटका लागि Object Read & Write भएको टोकन सिर्जना गर्नुहोस्, र access key id तथा secret यहाँ प्रतिलिपि गर्नुहोस्।','Dropbox app key'=>'Dropbox एप कुञ्जी','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'files.content.read, files.content.write र files.metadata.read अनुमतिहरूसहित dropbox.com/developers/apps मा एउटा एप सिर्जना गर्नुहोस् (Scoped access, App folder), र यसको App key यहाँ प्रतिलिपि गर्नुहोस्। बचत गर्नुहोस्, त्यसपछि Connect थिच्नुहोस्।','OAuth client id'=>'OAuth क्लाइन्ट आइडी','OAuth client secret'=>'OAuth क्लाइन्ट गोप्य कुञ्जी','Leave empty to keep the saved secret'=>'सुरक्षित गरिएको गोप्य कुञ्जी राख्न खाली छोड्नुहोस्','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'Google Cloud Console मा, Google Drive API सक्षम गर्नुहोस्, त्यसपछि यो ठेगानालाई अधिकृत रिडाइरेक्ट URI को रूपमा प्रयोग गरी "Web application" प्रकारको OAuth क्लाइन्ट सिर्जना गर्नुहोस्:','Save, then press Connect. The plugin only sees the files it creates.'=>'बचत गर्नुहोस्, त्यसपछि जडान गर्नुहोस् थिच्नुहोस्। प्लगइनले आफूले सिर्जना गरेका फाइलहरू मात्र देख्छ।','Folder inside the storage (optional)'=>'भण्डारण भित्रको फोल्डर (वैकल्पिक)','Save storage'=>'भण्डारण बचत गर्नुहोस्','Import a backup from another plugin or host'=>'अन्य प्लगइन वा होस्टबाट ब्याकअप आयात गर्नुहोस्','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, वा यसको .sql डम्प भएको WordPress साइटको कुनै पनि zip/tar सङ्ग्रहद्वारा बनाइएको ब्याकअपबाट साइट ल्याउनुहोस्। सामग्री wp-content मा जान्छ र डाटाबेसले यो साइटको डाटाबेसलाई प्रतिस्थापन गर्दछ; ठेगानाहरू स्वतः यो साइटको ठेगानामा परिवर्तन हुन्छन्।','Upload from your computer'=>'तपाईंको कम्प्युटरबाट अपलोड गर्नुहोस्','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'ब्याकअपको प्रत्येक फाइल एकै पटक छान्नुहोस् (UpdraftPlus ले धेरै फाइलहरू बनाउँछ)। ठूला फाइलहरू साना टुक्राहरूमा पठाइन्छ, त्यसैले तपाईंको होस्टको अपलोड सीमा लागू हुँदैन।','Or from links (Google Drive, Dropbox or any download address)'=>'वा लिङ्कहरूबाट (Google Drive, Dropbox वा कुनै पनि डाउनलोड ठेगाना)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'प्रति पङ्क्ति एक लिङ्क। Google Drive र Dropbox का लागि, फाइल "लिङ्क भएको जोकोही" सँग साझा गर्नुहोस् र त्यो लिङ्क टाँस्नुहोस्; त्यसपछि फेरि साझेदारी बन्द गर्नुहोस्।','Or a file already on this server'=>'वा पहिले नै यो सर्भरमा रहेको फाइल','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'FTP वा तपाईंको होस्टको फाइल प्रबन्धक मार्फत %s मा सङ्ग्रहहरू अपलोड गर्नुहोस् र यो पृष्ठ पुन: लोड गर्नुहोस्।','Or a deploy code from another site'=>'वा अर्को साइटबाट डिप्लोय कोड','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'यदि अर्को साइटले तपाईंलाई Zinn® Backups डिप्लोय कोड दिएको छ भने, यसको भण्डारण कुञ्जीहरू साझेदारी नगरी त्यो ब्याकअप यस साइटमा प्रतिलिपि गर्न यहाँ टाँस्नुहोस्। कोडले केही घण्टाका लागि काम गर्छ; यसलाई पासवर्ड जस्तै व्यवहार गर्नुहोस्।','Passphrase (only if that backup is encrypted)'=>'पासफ्रेज (यदि त्यो ब्याकअप इन्क्रिप्ट गरिएको छ भने मात्र)','Import'=>'आयात गर्नुहोस्','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'म बुझ्छु कि आयातले यस साइटको सामग्री र डाटाबेस बदल्छ। त्यसपछि, आयात गरिएको साइटको खाताबाट साइन इन गर्नुहोस्।','Moving to Zinn® hosting?'=>'Zinn® होस्टिङमा सार्दै हुनुहुन्छ?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® ले तपाईंको पुरानो होस्टबाट तपाईंको साइट स्थानान्तरण गरिदिन सक्छ। यदि तपाईंको पुरानो होस्टले तपाईंलाई FTP, SSH वा नियन्त्रण-प्यानल पहुँच दिँदैन भने, पुरानो साइटमा Zinn® Migrate स्थापना गर्नुहोस्; यसले एउटा सङ्ग्रह सिर्जना गर्दछ जुन तपाईं यहाँ आयात गर्न सक्नुहुन्छ वा Zinn® लाई हस्तान्तरण गर्न सक्नुहुन्छ।','What goes into a backup'=>'ब्याकअपमा के समावेश हुन्छ','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'WordPress का आफ्नै फाइलहरू (wp-admin, wp-includes) समावेश गर्नुहोस्। सामान्यतया आवश्यक पर्दैन: WordPress सधैं पुन: स्थापना गर्न सकिन्छ।','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'यी फोल्डरहरू वा फाइलहरूलाई पनि छोड्नुहोस् (प्रति पङ्क्ति एक, WordPress फोल्डरको सापेक्षमा)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'सधैँ बाहिर राखिएका: क्यासहरू, अद्यावधिक स्क्र्याच स्पेस, र अन्य ब्याकअप प्लगइनहरूका आफ्नै सङ्ग्रह फोल्डरहरू:','Size of each part (MB)'=>'प्रत्येक भागको आकार (MB)','Save settings'=>'सेटिङहरू सुरक्षित गर्नुहोस्','A backup part could not be opened for writing. Check that wp-content has free space.'=>'ब्याकअपको एक भाग लेख्नका लागि खोल्न सकिएन। wp-content मा खाली ठाउँ छ कि छैन जाँच गर्नुहोस्।','A backup part could not be written. Check that wp-content has free space.'=>'ब्याकअपको भाग लेख्न सकिएन। wp-content मा खाली ठाउँ छ भनी जाँच गर्नुहोस्।','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'पहिले Storage ट्याबमा भण्डारण गन्तव्य जडान गर्नुहोस्: ब्याकअपहरू यस सर्भरमा नभई तपाईंको आफ्नै भण्डारणमा राखिन्छन्।','Multisite networks are not supported yet.'=>'मल्टिसाइज सञ्जालहरू अझै समर्थित छैनन्।','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'यो सर्भरको PHP मा ZipArchive विस्तार छैन। यसलाई सक्षम गर्न आफ्नो होस्टलाई सोध्नुहोस्।','Starting'=>'सुरु हुँदैछ','Listing files'=>'फाइलहरू सूचीकृत गरिँदै छ','Backing up the database'=>'डाटाबेसको जगेडा प्रतिलिपि बनाइँदैछ','Packing files'=>'फाइलहरू प्याक गर्दै','Uploading to your storage'=>'तपाईंको भण्डारणमा अपलोड गरिँदैछ','Finishing'=>'सकिँदैछ','The backup reached an unknown stage.'=>'ब्याकअप अज्ञात चरणमा पुग्यो।','Backup %s started.'=>'%s को ब्याकअप सुरु भयो।','Found %1$s files (%2$s).'=>'%1$s फाइलहरू फेला परे (%2$s)।','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'डाटाबेस: %1$d तालिकाहरू, %2$s पङ्क्तिहरू, %3$s सङ्कुचित।','Backup complete: %1$s stored in %2$d destination.'=>'ब्याकअप पूरा भयो: %1$s %2$d गन्तव्यमा भण्डारण गरियो।' . "\0" . 'ब्याकअप पूरा भयो: %1$s लाई %2$d गन्तव्यहरूमा भण्डारण गरियो।','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'पहिले नै अपलोड गरिएका केही भागहरू तपाईंको भण्डारणबाट हटाउन सकिएन; तिनीहरू अपूर्ण ब्याकअप फोल्डरमा छन् र पुनर्स्थापनाका लागि कहिल्यै प्रस्ताव गरिँदैनन्।','A storage destination was removed while the backup was running.'=>'ब्याकअप चलिरहेको बेला भण्डारण गन्तव्य हटाइयो।','That is not a backup folder.'=>'त्यो ब्याकअप फोल्डर होइन।','That storage destination is no longer saved on this site.'=>'त्यो भण्डारण गन्तव्य अब यस साइटमा सुरक्षित गरिएको छैन।','Later incremental backups are built on this one. Delete those first.'=>'पछिल्ला वृद्धिशील ब्याकअपहरू यसैमा आधारित छन्। पहिले ती मेटाउनुहोस्।','This file is not an encrypted Zinn® Backups file.'=>'यो फाइल इन्क्रिप्ट गरिएको Zinn® Backups फाइल होइन।','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'ब्याकअप डिक्रिप्ट गर्न सकिएन: पासफ्रेज गलत छ वा फाइल क्षतिग्रस्त छ।','The encrypted backup file is incomplete.'=>'इन्क्रिप्ट गरिएको ब्याकअप फाइल अपूर्ण छ।','The database file could not be written. Check that wp-content has free space.'=>'डाटाबेस फाइल लेख्न सकिएन। wp-content मा खाली ठाउँ छ कि छैन जाँच गर्नुहोस्।','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'त्यो परिनियोजन कोड होइन। परिनियोजन कोड zbdeploy1 बाट सुरु हुन्छ।','That deploy code is damaged. Copy it again from the other site.'=>'त्यो डिप्लोय कोड बिग्रिएको छ। यसलाई अर्को साइटबाट पुन: प्रतिलिपि गर्नुहोस्।','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'तैनाथी कोडको म्याद सकिएको छ वा यसको ब्याकअप मेटाइएको छ। अर्को साइटमा नयाँ कोड बनाउनुहोस्।','That deploy code does not point at a Zinn® Backups backup.'=>'त्यो डिप्लोय कोडले Zinn® Backups ब्याकअपलाई सङ्केत गर्दैन।','The deploy code has expired. Make a new code on the other site.'=>'तैनाथी कोडको म्याद सकिएको छ। अर्को साइटमा नयाँ कोड बनाउनुहोस्।','The server stopped honouring partial downloads. Start the import again.'=>'सर्भरले आंशिक डाउनलोडहरू स्वीकार गर्न बन्द गर्यो। कृपया आयात पुन: सुरु गर्नुहोस्।','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'लिङ्कले फाइलको सट्टा वेब पृष्ठ खोल्यो। Google Drive र Dropbox को लागि, फाइललाई "लिङ्क भएको जो कोही" सँग सेयर गर्नुहोस् र त्यो लिङ्क टाँस्नुहोस्।','The link answered with HTTP %d.'=>'लिङ्कले HTTP %d मार्फत प्रतिक्रिया दियो।','The file list could not be written.'=>'फाइल सूची लेख्न सकिएन।','The storage service could not be reached: %s'=>'भण्डारण सेवामा पुग्न सकिएन: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s ले HTTP %2$d सँग प्रतिक्रिया दियो: %3$s','no details given'=>'कुनै विवरण दिइएको छैन','You are not allowed to manage backups.'=>'तपाईँलाई ब्याकअपहरू व्यवस्थापन गर्न अनुमति छैन।','Tick the box to confirm that the restore replaces this site’s files and database.'=>'पुनर्स्थापनाले यस साइटका फाइलहरू र डाटाबेस बदल्छ भनी पुष्टि गर्न बाकसमा चिन्ह लगाउनुहोस्।','Save the destination first.'=>'पहिले गन्तव्य बचत गर्नुहोस्।','Connected: a test file was written and removed.'=>'जडान भयो: परीक्षण फाइल लेखियो र हटाइयो।','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'पहिले तपाईंको Dropbox एपको एप कुञ्जी प्रविष्ट गर्नुहोस् (फारमको छेउमा रहेका चरणहरू हेर्नुहोस्)।','This kind of storage does not sign in.'=>'यस प्रकारको भण्डारण साइन इन गर्दैन।','The sign-in expired. Press Connect again.'=>'साइन-इनको समय समाप्त भयो। पुन: जडान गर्नुहोस् थिच्नुहोस्।','Dropbox is connected.'=>'Dropbox जोडिएको छ।','Settings saved.'=>'सेटिङहरू सुरक्षित गरियो।','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'अर्को ब्याकअप, पुनर्स्थापना वा आयात कार्य भइरहेको छ। यो समाप्त हुनको लागि पर्खनुहोस्, वा यसलाई रद्द गर्नुहोस्।','The upload was not started properly. Start again.'=>'अपलोड ठीकसँग सुरु भएन। पुन: सुरु गर्नुहोस्।','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'टुक्रा आइपुगेन। तपाईंको सर्भरले अपलोड आकार सीमित गर्न सक्छ; फेरि प्रयास गर्नुहोस्।','Tick the box to confirm that the import replaces this site’s content and database.'=>'आयातले यस साइटको सामग्री र डाटाबेस प्रतिस्थापन गर्दछ भनी पुष्टि गर्न बाकसमा चिन्ह लगाउनुहोस्।','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'आयात गर्नको लागि एउटा सङ्ग्रह छान्नुहोस्: यसलाई अपलोड गर्नुहोस्, लिङ्क टाँस्नुहोस्, वा आयात फोल्डरबाट एउटा छान्नुहोस्।','Hosting customer? Get %1$d%% off %2$s'=>'होस्टिङ ग्राहक हुनुहुन्छ? %2$s मा %1$d%% छुट पाउनुहोस्','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Zinn Digital® होस्टिङ ग्राहकको रूपमा तपाईंले आफ्नो पहिलो भुक्तानीमा %d%% छुटको लागि व्यक्तिगत कोड प्राप्त गर्नुहुन्छ। नवीकरणहरू सामान्य मूल्यमा हुन्छन्।','Get my %d%% code and go to checkout'=>'मेरो %d%% कोड लिनुहोस् र चेकआउटमा जानुहोस्','Sorry, you are not allowed to do that.'=>'माफ गर्नुहोस्, तपाईंलाई यो गर्न अनुमति छैन।','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'यो छुट राम्रो स्थितिमा रहेको सशुल्क होस्टिङ योजना भएका ग्राहकहरूका लागि हो। निःशुल्क परीक्षणहरू यसका लागि योग्य छैनन्।','You have already used your hosting-customer discount for this plugin.'=>'तपाईंले यो प्लगइनका लागि आफ्नो होस्टिङ-ग्राहक छुट पहिले नै प्रयोग गरिसक्नुभएको छ।','We could not get your code just now. Please try again in a few minutes.'=>'हामीले भर्खरै तपाईंको कोड प्राप्त गर्न सकेनौं। कृपया केही मिनेटमा पुन: प्रयास गर्नुहोस्।','Reading the backup'=>'ब्याकअप पढ्दै','Downloading the archive'=>'अभिलेख डाउनलोड गरिँदैछ','Recognising the archive'=>'अभिलेख पहिचान गर्दै','Restoring files'=>'फाइलहरू पुनर्स्थापना गरिँदैछ','Downloading the database'=>'डाटाबेस डाउनलोड गरिँदै छ','Restoring the database'=>'डाटाबेस पुनर्स्थापना गरिँदैछ','Updating the site address'=>'साइट ठेगाना अद्यावधिक गरिँदैछ','Switching to the restored database'=>'पुनर्स्थापित डाटाबेसमा स्विच गर्दै','The restore reached an unknown stage.'=>'पुनर्स्थापना अज्ञात चरणमा पुग्यो।','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'यो फोल्डरमा कुनै पूर्ण Zinn® Backups ब्याकअप छैन (मेनिफेस्ट हराइरहेको छ)।','This backup is encrypted. Enter its passphrase to restore it.'=>'यो जगेडा इन्क्रिप्ट गरिएको छ। यसलाई पुनर्स्थापना गर्न यसको पासफ्रेज प्रविष्ट गर्नुहोस्।','This incremental backup needs backup %s, which is no longer in the storage.'=>'यो वृद्धिशील ब्याकअपलाई ब्याकअप %s चाहिन्छ, जुन अब भण्डारणमा छैन।','Restoring the backup of %1$s (%2$d file parts).'=>'%1$s को ब्याकअप पुनर्स्थापना गरिँदैछ (%2$d फाइल भागहरू)।','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'%1$s फाइल अधिलेखन गर्न सकिएन किनभने यो साइटलाई यसलाई परिवर्तन गर्ने अनुमति छैन, र यसलाई जस्तो थियो त्यस्तै छोडियो: %2$s' . "\0" . 'यो साइटलाई ती फाइलहरू परिवर्तन गर्ने अनुमति नभएकाले %1$s फाइलहरू अधिलेखन गर्न सकिएन, र तिनीहरूलाई जस्ताको तस्तै छोडियो: %2$s','Restored %s files.'=>'%s फाइलहरू पुनर्स्थापित गरियो।','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'डाउनलोड गरेपछि %s यसको चेकसमसँग मिलेन। भण्डारणमा रहेको प्रतिलिपि क्षतिग्रस्त हुन सक्छ।','%s did not arrive. Upload it again.'=>'%s आइपुगेन। कृपया यसलाई फेरि अपलोड गर्नुहोस्।','Recognised: %s.'=>'पहिचान गरियो: %s।','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'wp-content मा %1$s फाइलहरू आयात गरियो (%2$s छुटाइएका छन्: क्यासहरू, ड्रप-इनहरू र अन्य ब्याकअप प्लगइनहरूका फोल्डरहरू)।','The archive has no database dump, so only files were imported.'=>'संग्रहमा कुनै डाटाबेस डम्प छैन, त्यसैले फाइलहरू मात्र आयात गरियो।','Database restored into %d temporary tables.'=>'डेटाबेस %d अस्थायी तालिकाहरूमा पुनर्स्थापित गरियो।','%s has no WordPress tables in it and was skipped.'=>'%s मा कुनै पनि WordPress तालिकाहरू छैनन् र यसलाई छोडियो।','The backup’s database has no WordPress tables, so nothing was replaced.'=>'ब्याकअपको डाटाबेसमा कुनै पनि WordPress तालिकाहरू छैनन्, त्यसैले केही पनि प्रतिस्थापन गरिएन।','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'यो ब्याकअप मल्टिसाइज नेटवर्कको हो। नेटवर्कलाई एकल साइटमा पुनर्स्थापना गर्न समर्थित छैन।','Moving the content from %1$s to %2$s.'=>'%1$s बाट %2$s मा सामग्री सार्दै।','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'पुनर्स्थापना पूरा भयो। यदि तपाईं साइन आउट हुनुभएको छ भने, पुनर्स्थापित साइटको खाताबाट साइन इन गर्नुहोस्।','Restore complete.'=>'पुनर्स्थापना पूरा भयो।','%1$s — trying again in %2$d seconds.'=>'%1$s — %2$d सेकेन्डमा पुन: प्रयास गर्दैछ।','Cancelled.'=>'रद्द गरियो।','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'ब्याकअपहरू एउटा भण्डारण गन्तव्यमा जान्छन्। फरक प्रयोग गर्नका लागि तपाईंसँग भएकोलाई सम्पादन गर्नुहोस् वा हटाउनुहोस्।','The database file could not be opened.'=>'डेटाबेस फाइल खोल्न सकिएन।','The database refused a statement from the backup: %1$s (%2$s…)'=>'डाटाबेसले ब्याकअपबाट एक स्टेटमेन्ट अस्वीकार गर्‍यो: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'पुनर्स्थापित गरिएका तालिकाहरू साट्न सकिएन: %s। तपाईंको साइट अपरिवर्तित छ।','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'अस्थायी ब्याकअप फाइलहरूका लागि कुनै लेख्न मिल्ने फोल्डर छैन। wp-content लाई लेख्न मिल्ने बनाउनुहोस् र पुन: प्रयास गर्नुहोस्।','Could not create a folder for this job.'=>'यो कार्यका लागि फोल्डर सिर्जना गर्न सकिएन।','%s — guides and services'=>'%s — निर्देशिकाहरू र सेवाहरू','User guides'=>'प्रयोगकर्ता गाइडहरू','Read the %s user guide'=>'%s प्रयोगकर्ता निर्देशिका पढ्नुहोस्','Hide this'=>'यो लुकाउनुहोस्','Zinn® hosting for WordPress'=>'WordPress का लागि Zinn® होस्टिङ','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, दैनिक ब्याकअप, नि:शुल्क माइग्रेसन र एक भन्दा बढी साइट चलाउने व्यक्तिहरूका लागि बनाइएको नियन्त्रण प्यानल।','The Zinn® marketplace'=>'Zinn® बजार','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'दुवै पक्ष सन्तुष्ट नभएसम्म रकम सुरक्षित रूपमा राखेर, स्थापित साइटहरू, डोमेनहरू र लिङ्क प्लेसमेन्टहरू किन्नुहोस् र बेच्नुहोस्।','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — यसैलाई आफ्नो पेशा बनाएका व्यक्तिहरूलाई काममा लगाउनुहोस्','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'हाम्रो विश्वव्यापी फ्रिलान्स बजार: लेखक, डिजाइनर, विकासकर्ता र SEO विशेषज्ञहरूबाट १०,००० भन्दा बढी तयार सेवाहरू ब्राउज गर्नुहोस्, वा परियोजना पोस्ट गरेर उनीहरूलाई बोलपत्र पेश गर्न दिनुहोस्।','See the Zinn Digital® release notes.'=>'Zinn Digital® रिलीज नोटहरू हेर्नुहोस्।','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Zinn® अद्यावधिक सेवाले यस अद्यावधिकको लागि डाउनलोड लिङ्क जारी गरेन। यो साइट Zinn® प्लेटफर्ममा पुग्न सक्छ कि सक्दैन भनी जाँच गर्नुहोस्, त्यसपछि फेरि प्रयास गर्नुहोस्।','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Zinn® अद्यावधिक सेवा (%s) बाट अद्यावधिक डाउनलोड गर्न सकिएन। कृपया केही मिनेटपछि पुन: प्रयास गर्नुहोस्।','The downloaded update failed its integrity check and was not installed.'=>'डाउनलोड गरिएको अपडेटले आफ्नो अखण्डता जाँच पूरा गर्न सकेन र स्थापना गरिएन।','The zip archive could not be opened. It may be damaged or incomplete.'=>'जिप संग्रह खोल्न सकिएन। यो क्षतिग्रस्त वा अपूर्ण हुन सक्छ।','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'यो .wpress फाइलले हामीले पढ्न नसक्ने ढाँचा प्रयोग गर्दछ (यो All-in-One WP Migration द्वारा कम्प्रेस वा इन्क्रिप्ट गरिएको हुन सक्छ)। कृपया यसलाई इन्क्रिप्सन बिना पुन: निर्यात गर्नुहोस्।','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'यो Duplicator “DupArchive” (.daf) फाइल हो। Duplicator मा, सङ्ग्रह ढाँचालाई ZIP मा सेट गरी प्याकेज पुन: निर्माण गर्नुहोस्, त्यसपछि त्यसलाई आयात गर्नुहोस्।','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'यो UpdraftPlus डाटाबेस ब्याकअप इन्क्रिप्ट गरिएको छ। यसलाई UpdraftPlus मा डिक्रिप्ट गर्नुहोस् (वा डाटाबेस इन्क्रिप्शन बन्द गर्नुहोस् र पुन: ब्याकअप लिनुहोस्), त्यसपछि यसलाई आयात गर्नुहोस्।','Database dump'=>'डेटाबेस डम्प','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s हामीले पढ्न सक्ने ब्याकअप सङ्ग्रह होइन (zip, tar, tar.gz, .wpress, .sql वा .sql.gz)।','Website archive'=>'वेबसाइट सङ्ग्रह','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s मा कुनै पनि WordPress सामग्री छैन (कुनै wp-content फोल्डर छैन र कुनै डाटाबेस डम्प छैन)।','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'यो .wpress फाइल All-in-One WP Migration द्वारा इन्क्रिप्ट वा कम्प्रेस गरिएको छ। कृपया इन्क्रिप्शन र कम्प्रेसन बन्द गरेर यसलाई फेरि निर्यात गर्नुहोस्, त्यसपछि त्यसलाई आयात गर्नुहोस्।','Other S3-compatible storage'=>'अन्य S3-मिल्दो भण्डारण','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 वा S3-मिल्दो','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'यो साइटमा भण्डारण कुञ्जीहरू पढ्न सकिएन। भण्डारण ट्याबमा गोप्य कुञ्जी फेरि प्रविष्ट गर्नुहोस्।','This kind of storage is not known.'=>'यस प्रकारको भण्डारण अज्ञात छ।','Choose a kind of storage.'=>'भण्डारणको प्रकार छान्नुहोस्।','Enter the bucket name and the access key.'=>'बकेटको नाम र पहुँच कुञ्जी प्रविष्ट गर्नुहोस्।','Enter your Cloudflare account id (or the full R2 endpoint).'=>'आफ्नो Cloudflare खाता आईडी (वा पूर्ण R2 अन्तिम बिन्दु) प्रविष्ट गर्नुहोस्।','Enter the endpoint address of your storage.'=>'आफ्नो भण्डारणको अन्त्यबिन्दु ठेगाना प्रविष्ट गर्नुहोस्।','Enter the OAuth client id from your Google Cloud project.'=>'तपाईंको Google Cloud परियोजनाबाट OAuth client id प्रविष्ट गर्नुहोस्।','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox ले रिफ्रेस टोकन फर्काएन। कृपया जडान फेरि सुरु गर्नुहोस्।','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox जडान गरिएको छैन। भण्डारण ट्याबमा यसलाई पुन: जडान गर्नुहोस्।','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google ले रिफ्रेस टोकन फर्काएन। यो साइटलाई आफ्नो Google खाताको तेस्रो-पक्ष पहुँचबाट हटाउनुहोस् र पुन: जडान गर्नुहोस्।','That file is not in Google Drive any more.'=>'त्यो फाइल अब Google Drive मा छैन।','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive जडान गरिएको छैन। भण्डारण ट्याबमा यसलाई पुन: जडान गर्नुहोस्।','The storage service did not start the upload.'=>'भण्डारण सेवाले अपलोड सुरु गरेन।','The storage service sent a reply that could not be read.'=>'भण्डारण सेवाले पढ्न नसकिने प्रतिक्रिया पठायो।','A temporary backup file could not be read.'=>'अस्थायी ब्याकअप फाइल पढ्न सकिएन।','A deploy link is read-only.'=>'परिनियोजन लिङ्क पढ्नका लागि मात्र हो।','The deploy code has no link for a file this backup needs.'=>'डिप्लोय कोडमा यो ब्याकअपलाई आवश्यक पर्ने फाइलको लागि कुनै लिङ्क छैन।','The deploy link'=>'तैनाथी लिङ्क']];